import { useEffect, useMemo, useState, type ReactNode } from 'react'
import { Plus, Save, Trash2, RefreshCw, Power, PowerOff, Play, LockKeyhole, Trophy, RotateCcw } from 'lucide-react'
import { PageHeader } from '../../components/layout/PageHeader'
import { StatusBadge } from '../../components/status/StatusBadge'
import { Button } from '../../lib/shadcn/button'
import { toast } from '../../lib/shadcn/sonner'
import { supabase } from '../../lib/supabase'

const inputCls='h-9 w-full rounded-md border border-border bg-background px-2.5 text-sm outline-none focus:ring-1 focus:ring-ring'
const areaCls='min-h-20 w-full rounded-md border border-border bg-background px-2.5 py-2 text-sm outline-none focus:ring-1 focus:ring-ring'
const errText=(e:unknown)=>e instanceof Error?e.message:'Operation failed'
const fmt=(v?:string|null)=>v?new Date(v).toLocaleString():'—'
function Field({label,children}:{label:string;children:ReactNode}){return <label className="flex flex-col gap-1.5 text-xs font-medium text-muted-foreground"><span>{label}</span>{children}</label>}
function Section({title,children,actions}:{title:string;children:ReactNode;actions?:ReactNode}){return <section className="rounded-lg border border-border bg-card p-density-lg shadow-retool-sm"><div className="mb-density-md flex items-center justify-between gap-3"><h2 className="text-base font-semibold">{title}</h2>{actions}</div>{children}</section>}
function JsonField({value,onChange}:{value:string;onChange:(v:string)=>void}){return <textarea className={areaCls} value={value} onChange={e=>onChange(e.target.value)} placeholder="{}"/>}
function parseJson(v:string){try{return v.trim()?JSON.parse(v):{}}catch{throw new Error('JSON must be valid.')}}
function Metric({label,value}:{label:string;value:ReactNode}){return <div className="rounded-lg border border-border bg-card p-density-lg shadow-retool-sm"><div className="text-xs uppercase tracking-wide text-muted-foreground">{label}</div><div className="mt-1 text-2xl font-semibold">{value}</div></div>}

const bonusDefaults={partner_id:'',brand_name:'Unknown Brand',brand_logo_url:'',title:'',slug:'',description:'',bonus_type:'other',delivery_type:'code',code:'',affiliate_url:'',image_url:'',offer_value:'',terms:'',starts_at:'',expires_at:'',status:'draft',featured:false,sort_order:0,max_claims:'',bonus_access_type:'public'}

export function BonusesPage(){
 const [rows,setRows]=useState<any[]>([]),[partners,setPartners]=useState<any[]>([]),[features,setFeatures]=useState<any[]>([]),[rewards,setRewards]=useState<any[]>([]);const [editing,setEditing]=useState<any|null>(null),[form,setForm]=useState<any>(bonusDefaults),[reward,setReward]=useState<any|null>(null),[loading,setLoading]=useState(true)
 async function load(){setLoading(true);try{const [{data:b,error:be},{data:p,error:pe},{data:f,error:fe},{data:r,error:re}]=await Promise.all([supabase.from('bonuses').select('*').order('sort_order').order('created_at',{ascending:false}),supabase.from('partners').select('*').order('name'),supabase.from('platform_reward_features').select('*').order('feature_key'),supabase.from('reward_catalog').select('*').order('category').order('reward_key')]);if(be)throw be;if(pe)throw pe;if(fe)throw fe;if(re)throw re;setRows(b??[]);setPartners(p??[]);setFeatures(f??[]);setRewards(r??[])}catch(e){toast.error(errText(e))}finally{setLoading(false)}}useEffect(()=>{void load()},[])
 function fresh(){setEditing(null);setForm({...bonusDefaults})}function edit(r:any){setEditing(r.id);setForm({...r,partner_id:r.partner_id??'',max_claims:r.max_claims??'',starts_at:r.starts_at?.slice(0,16)??'',expires_at:r.expires_at?.slice(0,16)??''})}
 async function save(){try{if(!form.title.trim())throw new Error('Title is required.');const p={...form,partner_id:form.partner_id||null,max_claims:form.max_claims===''?null:Number(form.max_claims),sort_order:Number(form.sort_order)||0,starts_at:form.starts_at||null,expires_at:form.expires_at||null,brand_name:form.brand_name.trim()||'Unknown Brand'};delete p.id;delete p.created_at;delete p.updated_at;const {error}=editing?await supabase.from('bonuses').update(p).eq('id',editing):await supabase.from('bonuses').insert(p);if(error)throw error;toast.success(editing?'Bonus updated':'Bonus created');fresh();await load()}catch(e){toast.error(errText(e))}}
 async function remove(id:string){if(!window.confirm('Delete this bonus?'))return;try{const {error}=await supabase.from('bonuses').delete().eq('id',id);if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 async function status(id:string,next:string){try{const {error}=await supabase.rpc('admin_set_bonus_status',{p_bonus_id:id,p_status:next});if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 async function featured(id:string,next:boolean){try{const {error}=await supabase.rpc('admin_set_bonus_featured',{p_bonus_id:id,p_featured:next});if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 async function saveReward(){try{if(!reward) return;const p={...reward,points:Number(reward.points),max_awards:reward.max_awards===''?null:Number(reward.max_awards),cooldown_seconds:reward.cooldown_seconds===''?null:Number(reward.cooldown_seconds),conditions:parseJson(reward.conditions),metadata:parseJson(reward.metadata)};delete p.created_at;delete p.updated_at;const {error}=await supabase.from('reward_catalog').update(p).eq('reward_key',reward.reward_key);if(error)throw error;toast.success('Reward updated');setReward(null);await load()}catch(e){toast.error(errText(e))}}
 async function toggleFeature(key:string,next:boolean){try{const {error}=await supabase.rpc('set_reward_feature_enabled',{p_feature_key:key,p_enabled:next});if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 async function toggleReward(key:string,next:boolean){try{const {error}=await supabase.rpc('set_reward_enabled',{p_reward_key:key,p_enabled:next});if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Bonuses" description="Promotions, bonus access rules, reward catalog and platform reward switches." actions={<><Button variant="outline" onClick={()=>void load()} disabled={loading}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button onClick={fresh}><Plus className="h-4 w-4"/>New bonus</Button></>}/><div className="grid gap-density-md md:grid-cols-3"><Metric label="Active" value={rows.filter(r=>r.status==='active').length}/><Metric label="Featured" value={rows.filter(r=>r.featured).length}/><Metric label="Reward rules" value={rewards.length}/></div>
 <Section title={editing?'Edit bonus':'Create bonus'}><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-4"><Field label="Partner"><select className={inputCls} value={form.partner_id} onChange={e=>setForm({...form,partner_id:e.target.value})}><option value="">No partner</option>{partners.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Brand"><input className={inputCls} value={form.brand_name} onChange={e=>setForm({...form,brand_name:e.target.value})}/></Field><Field label="Title"><input className={inputCls} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></Field><Field label="Slug"><input className={inputCls} value={form.slug} onChange={e=>setForm({...form,slug:e.target.value})}/></Field><Field label="Bonus type"><select className={inputCls} value={form.bonus_type} onChange={e=>setForm({...form,bonus_type:e.target.value})}>{['deposit_bonus','free_bet','free_spin','cashback','promo_code','other'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Delivery"><select className={inputCls} value={form.delivery_type} onChange={e=>setForm({...form,delivery_type:e.target.value})}>{['code','link','code_and_link'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Access"><select className={inputCls} value={form.bonus_access_type} onChange={e=>setForm({...form,bonus_access_type:e.target.value})}>{['public','challenge','winner'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Status"><select className={inputCls} value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{['draft','active','paused','expired','archived'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Code"><input className={inputCls} value={form.code??''} onChange={e=>setForm({...form,code:e.target.value})}/></Field><Field label="Affiliate URL"><input className={inputCls} value={form.affiliate_url??''} onChange={e=>setForm({...form,affiliate_url:e.target.value})}/></Field><Field label="Offer value"><input className={inputCls} value={form.offer_value??''} onChange={e=>setForm({...form,offer_value:e.target.value})}/></Field><Field label="Max claims"><input className={inputCls} type="number" value={form.max_claims} onChange={e=>setForm({...form,max_claims:e.target.value})}/></Field><Field label="Starts"><input className={inputCls} type="datetime-local" value={form.starts_at} onChange={e=>setForm({...form,starts_at:e.target.value})}/></Field><Field label="Expires"><input className={inputCls} type="datetime-local" value={form.expires_at} onChange={e=>setForm({...form,expires_at:e.target.value})}/></Field><Field label="Sort order"><input className={inputCls} type="number" value={form.sort_order} onChange={e=>setForm({...form,sort_order:e.target.value})}/></Field><Field label="Featured"><input type="checkbox" checked={!!form.featured} onChange={e=>setForm({...form,featured:e.target.checked})}/></Field><div className="md:col-span-2 xl:col-span-4"><Field label="Description"><textarea className={areaCls} value={form.description??''} onChange={e=>setForm({...form,description:e.target.value})}/></Field></div><div className="md:col-span-2 xl:col-span-4"><Field label="Terms"><textarea className={areaCls} value={form.terms??''} onChange={e=>setForm({...form,terms:e.target.value})}/></Field></div><Field label="Brand logo URL"><input className={inputCls} value={form.brand_logo_url??''} onChange={e=>setForm({...form,brand_logo_url:e.target.value})}/></Field><Field label="Image URL"><input className={inputCls} value={form.image_url??''} onChange={e=>setForm({...form,image_url:e.target.value})}/></Field></div><div className="mt-density-md flex justify-end gap-2"><Button variant="outline" onClick={fresh}>Clear</Button><Button onClick={()=>void save()}><Save className="h-4 w-4"/>Save bonus</Button></div></Section>
 <Section title="Bonus catalog"><div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th className="py-2">Offer</th><th>Type</th><th>Access</th><th>Status</th><th>Partner</th><th className="text-right">Actions</th></tr></thead><tbody>{rows.map(r=><tr key={r.id} className="border-b border-border/70"><td className="py-2"><div className="font-medium">{r.title}</div><div className="text-xs text-muted-foreground">{r.brand_name}</div></td><td>{r.bonus_type}</td><td>{r.bonus_access_type}</td><td><StatusBadge status={r.status} dense/></td><td>{partners.find(p=>p.id===r.partner_id)?.name??'—'}</td><td><div className="flex justify-end gap-1"><Button variant="ghost" size="sm" onClick={()=>edit(r)}>Edit</Button><Button variant="ghost" size="sm" onClick={()=>void featured(r.id,!r.featured)}>{r.featured?'Unfeature':'Feature'}</Button>{r.status==='active'?<Button variant="ghost" size="sm" onClick={()=>void status(r.id,'paused')}><PowerOff className="h-3.5 w-3.5"/></Button>:<Button variant="ghost" size="sm" onClick={()=>void status(r.id,'active')}><Power className="h-3.5 w-3.5"/></Button>}<Button variant="ghost" size="sm" onClick={()=>void remove(r.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div></td></tr>)}</tbody></table></div></Section>
 <Section title="Reward catalog"><div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th className="py-2">Key</th><th>Title</th><th>Category</th><th>Points</th><th>Frequency</th><th>Enabled</th><th/></tr></thead><tbody>{rewards.map(r=><tr key={r.reward_key} className="border-b border-border/70"><td className="py-2 font-mono text-xs">{r.reward_key}</td><td>{r.title}</td><td>{r.category}</td><td>{r.points}</td><td>{r.frequency}</td><td><StatusBadge status={r.enabled?'ENABLED':'DISABLED'} dense/></td><td><div className="flex justify-end gap-1"><Button variant="ghost" size="sm" onClick={()=>setReward({...r,conditions:JSON.stringify(r.conditions??{},null,2),metadata:JSON.stringify(r.metadata??{},null,2),max_awards:r.max_awards??'',cooldown_seconds:r.cooldown_seconds??''})}>Edit</Button><Button variant="ghost" size="sm" onClick={()=>void toggleReward(r.reward_key,!r.enabled)}>{r.enabled?'Disable':'Enable'}</Button></div></td></tr>)}</tbody></table></div>{reward&&<div className="mt-density-md rounded-md border border-border p-3"><div className="grid gap-density-md md:grid-cols-3"><Field label="Title"><input className={inputCls} value={reward.title} onChange={e=>setReward({...reward,title:e.target.value})}/></Field><Field label="Points"><input className={inputCls} type="number" value={reward.points} onChange={e=>setReward({...reward,points:e.target.value})}/></Field><Field label="Frequency"><select className={inputCls} value={reward.frequency} onChange={e=>setReward({...reward,frequency:e.target.value})}>{['once','daily','unlimited','manual'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Max awards"><input className={inputCls} type="number" value={reward.max_awards} onChange={e=>setReward({...reward,max_awards:e.target.value})}/></Field><Field label="Cooldown seconds"><input className={inputCls} type="number" value={reward.cooldown_seconds} onChange={e=>setReward({...reward,cooldown_seconds:e.target.value})}/></Field><Field label="Feature key"><input className={inputCls} value={reward.feature_key??''} onChange={e=>setReward({...reward,feature_key:e.target.value})}/></Field><div className="md:col-span-3"><Field label="Conditions JSON"><JsonField value={reward.conditions} onChange={v=>setReward({...reward,conditions:v})}/></Field></div><div className="md:col-span-3"><Field label="Metadata JSON"><JsonField value={reward.metadata} onChange={v=>setReward({...reward,metadata:v})}/></Field></div></div><div className="mt-2 flex justify-end gap-2"><Button variant="outline" onClick={()=>setReward(null)}>Cancel</Button><Button onClick={()=>void saveReward()}><Save className="h-4 w-4"/>Save reward</Button></div></div>}</Section>
 <Section title="Reward feature switches"><div className="grid gap-2 md:grid-cols-2">{features.map(f=><div key={f.feature_key} className="flex items-center justify-between rounded-md border border-border p-3"><div><div className="font-medium">{f.title}</div><div className="text-xs text-muted-foreground">{f.feature_key}</div></div><Button size="sm" variant={f.enabled?'outline':'default'} onClick={()=>void toggleFeature(f.feature_key,!f.enabled)}>{f.enabled?'Enabled':'Disabled'}</Button></div>)}</div></Section></div>
}

export function GiveawaysPage(){
 const [rows,setRows]=useState<any[]>([]),[challenges,setChallenges]=useState<any[]>([]),[selected,setSelected]=useState<any|null>(null);const [form,setForm]=useState<any>(null);const [newForm,setNewForm]=useState<any>({challenge_id:'',slug:'',title:'',subtitle:'',description:'',giveaway_type:'general',status:'draft',starts_at:'',ends_at:'',featured:false,sort_order:0,image_url:'',cover_url:'',badge_text:'',prize_headline:'',participant_label:'',show_participant_count:true,show_winner_count:true,display_type:'general',metadata:'{}'});const [tasks,setTasks]=useState<any[]>([]),[prizes,setPrizes]=useState<any[]>([])
 async function load(){try{const [{data:g,error:ge},{data:c,error:ce}]=await Promise.all([supabase.from('giveaways').select('*').order('sort_order').order('created_at',{ascending:false}),supabase.from('challenges').select('id,title,status,starts_at,ends_at').order('created_at',{ascending:false})]);if(ge)throw ge;if(ce)throw ce;setRows(g??[]);setChallenges(c??[]);if(selected){const [t,p]=await Promise.all([supabase.from('challenge_tasks').select('*').eq('challenge_id',selected.challenge_id).order('task_order'),supabase.from('challenge_prizes').select('*').eq('challenge_id',selected.challenge_id).order('sort_order')]);setTasks(t.data??[]);setPrizes(p.data??[])}}catch(e){toast.error(errText(e))}}useEffect(()=>{void load()},[])
 function pick(r:any){setSelected(r);setForm({...r,starts_at:r.starts_at?.slice(0,16)??'',ends_at:r.ends_at?.slice(0,16)??'',metadata:JSON.stringify(r.metadata??{},null,2)})}
 async function create(){try{if(!newForm.challenge_id)throw new Error('Select a challenge.');const p={...newForm,starts_at:newForm.starts_at||null,ends_at:newForm.ends_at||null,sort_order:Number(newForm.sort_order)||0,metadata:parseJson(newForm.metadata)};const {data,error}=await supabase.from('giveaways').insert(p).select().single();if(error)throw error;toast.success('Giveaway created');setNewForm({...newForm,title:'',slug:'',subtitle:'',description:''});await load();pick(data)}catch(e){toast.error(errText(e))}}
 async function update(){try{const p={...form,starts_at:form.starts_at||null,ends_at:form.ends_at||null,sort_order:Number(form.sort_order)||0,metadata:parseJson(form.metadata)};delete p.id;delete p.created_at;delete p.updated_at;const {error}=await supabase.from('giveaways').update(p).eq('id',selected.id);if(error)throw error;toast.success('Giveaway updated');await load()}catch(e){toast.error(errText(e))}}
 async function remove(){if(!selected||!window.confirm('Delete this giveaway?'))return;try{const {error}=await supabase.from('giveaways').delete().eq('id',selected.id);if(error)throw error;setSelected(null);await load()}catch(e){toast.error(errText(e))}}
 async function createTask(){try{const {error}=await supabase.from('challenge_tasks').insert({challenge_id:selected.challenge_id,task_key:`task-${Date.now()}`,title:'New task',description:'',task_type:'custom',verification_method:'manual',is_required:true,task_order:tasks.length,config:{},metadata:{}});if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 async function createPrize(){try{const {error}=await supabase.from('challenge_prizes').insert({challenge_id:selected.challenge_id,title:'New prize',description:'',prize_type:'points',award_trigger:'winner',points_amount:100,quantity:1,sort_order:prizes.length,custom_data:{},metadata:{}});if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 async function del(table:string,id:string){if(!window.confirm('Delete item?'))return;try{const {error}=await supabase.from(table).delete().eq('id',id);if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 const challengeOptions=useMemo(()=>challenges,[challenges])
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Giveaways" description="Giveaway presentation records linked to one challenge, including tasks and prizes." actions={<Button variant="outline" onClick={()=>void load()}><RefreshCw className="h-4 w-4"/>Refresh</Button>}/><Section title="Create giveaway"><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-4"><Field label="Challenge"><select className={inputCls} value={newForm.challenge_id} onChange={e=>setNewForm({...newForm,challenge_id:e.target.value})}><option value="">Select…</option>{challengeOptions.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></Field><Field label="Title"><input className={inputCls} value={newForm.title} onChange={e=>setNewForm({...newForm,title:e.target.value})}/></Field><Field label="Slug"><input className={inputCls} value={newForm.slug} onChange={e=>setNewForm({...newForm,slug:e.target.value})}/></Field><Field label="Display type"><select className={inputCls} value={newForm.display_type} onChange={e=>setNewForm({...newForm,display_type:e.target.value})}>{['general','social','telegram','prediction','random_draw','mixed','tournament','pickrush','prize_pool','special','custom'].map(v=><option key={v}>{v}</option>)}</select></Field></div><div className="mt-density-md flex justify-end"><Button onClick={()=>void create()}><Plus className="h-4 w-4"/>Create</Button></div></Section><Section title="Giveaways"><div className="grid gap-2">{rows.map(r=><button key={r.id} onClick={()=>pick(r)} className={`rounded-md border p-3 text-left ${selected?.id===r.id?'border-foreground':'border-border'}`}><div className="flex items-center justify-between"><div><div className="font-medium">{r.title}</div><div className="text-xs text-muted-foreground">/{r.slug} · {r.display_type}</div></div><StatusBadge status={r.status} dense/></div></button>)}</div></Section>{selected&&form&&<Section title={`Manage: ${selected.title}`} actions={<Button variant="ghost" size="sm" onClick={remove}><Trash2 className="h-3.5 w-3.5"/>Delete</Button>}><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-4"><Field label="Challenge"><select className={inputCls} value={form.challenge_id} onChange={e=>setForm({...form,challenge_id:e.target.value})}>{challenges.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></Field><Field label="Title"><input className={inputCls} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></Field><Field label="Subtitle"><input className={inputCls} value={form.subtitle??''} onChange={e=>setForm({...form,subtitle:e.target.value})}/></Field><Field label="Slug"><input className={inputCls} value={form.slug} onChange={e=>setForm({...form,slug:e.target.value})}/></Field><Field label="Type"><select className={inputCls} value={form.giveaway_type} onChange={e=>setForm({...form,giveaway_type:e.target.value})}>{['general','social','telegram','prediction','random_draw','mixed','tournament','special'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Status"><select className={inputCls} value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{['draft','active','paused','ended','cancelled'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Starts"><input className={inputCls} type="datetime-local" value={form.starts_at} onChange={e=>setForm({...form,starts_at:e.target.value})}/></Field><Field label="Ends"><input className={inputCls} type="datetime-local" value={form.ends_at} onChange={e=>setForm({...form,ends_at:e.target.value})}/></Field><Field label="Featured"><input type="checkbox" checked={!!form.featured} onChange={e=>setForm({...form,featured:e.target.checked})}/></Field><Field label="Sort order"><input className={inputCls} type="number" value={form.sort_order} onChange={e=>setForm({...form,sort_order:e.target.value})}/></Field><Field label="Image URL"><input className={inputCls} value={form.image_url??''} onChange={e=>setForm({...form,image_url:e.target.value})}/></Field><Field label="Cover URL"><input className={inputCls} value={form.cover_url??''} onChange={e=>setForm({...form,cover_url:e.target.value})}/></Field><Field label="Badge text"><input className={inputCls} value={form.badge_text??''} onChange={e=>setForm({...form,badge_text:e.target.value})}/></Field><Field label="Prize headline"><input className={inputCls} value={form.prize_headline??''} onChange={e=>setForm({...form,prize_headline:e.target.value})}/></Field><Field label="Participant label"><input className={inputCls} value={form.participant_label??''} onChange={e=>setForm({...form,participant_label:e.target.value})}/></Field><Field label="Show participants"><input type="checkbox" checked={!!form.show_participant_count} onChange={e=>setForm({...form,show_participant_count:e.target.checked})}/></Field><Field label="Show winners"><input type="checkbox" checked={!!form.show_winner_count} onChange={e=>setForm({...form,show_winner_count:e.target.checked})}/></Field><div className="md:col-span-2 xl:col-span-4"><Field label="Description"><textarea className={areaCls} value={form.description??''} onChange={e=>setForm({...form,description:e.target.value})}/></Field></div><div className="md:col-span-2 xl:col-span-4"><Field label="Metadata JSON"><JsonField value={form.metadata} onChange={v=>setForm({...form,metadata:v})}/></Field></div></div><div className="mt-density-md flex justify-end"><Button onClick={()=>void update()}><Save className="h-4 w-4"/>Save</Button></div><div className="mt-density-xl grid gap-density-lg xl:grid-cols-2"><div><div className="mb-2 font-semibold">Tasks</div>{tasks.map(t=><div key={t.id} className="mb-2 flex items-center justify-between rounded-md border border-border p-3"><div><div className="font-medium">{t.title}</div><div className="text-xs text-muted-foreground">{t.task_type} · {t.verification_method}</div></div><Button variant="ghost" size="sm" onClick={()=>void del('challenge_tasks',t.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div>)}<Button variant="outline" size="sm" onClick={()=>void createTask()}><Plus className="h-3.5 w-3.5"/>Add task</Button></div><div><div className="mb-2 font-semibold">Prizes</div>{prizes.map(p=><div key={p.id} className="mb-2 flex items-center justify-between rounded-md border border-border p-3"><div><div className="font-medium">{p.title}</div><div className="text-xs text-muted-foreground">{p.prize_type} · {p.award_trigger}</div></div><Button variant="ghost" size="sm" onClick={()=>void del('challenge_prizes',p.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div>)}<Button variant="outline" size="sm" onClick={()=>void createPrize()}><Plus className="h-3.5 w-3.5"/>Add prize</Button></div></div></Section>}</div>
}

export function PickRushPage(){
 const [rows,setRows]=useState<any[]>([]),[selected,setSelected]=useState<any|null>(null),[form,setForm]=useState<any>(null),[participants,setParticipants]=useState<any[]>([])
 async function load(){try{const {data,error}=await supabase.from('pickrush_contests').select('*, partners(name)').order('starts_at',{ascending:false});if(error)throw error;setRows(data??[]);if(selected){const c=(data??[]).find((r:any)=>r.id===selected.id);if(c){setSelected(c);setForm(c);const {data:p,error:pe}=await supabase.rpc('get_pickrush_participants',{p_contest_id:c.id});if(pe)throw pe;setParticipants(Array.isArray(p)?p:[])}}}catch(e){toast.error(errText(e))}}useEffect(()=>{void load()},[])
 function pick(r:any){setSelected(r);setForm(r)}
 async function create(){try{const {error}=await supabase.rpc('create_pickrush_contest',{p_title:'New Pick Rush',p_slug:`pickrush-${Date.now()}`,p_description:'',p_starts_at:new Date().toISOString(),p_ends_at:new Date(Date.now()+86400000).toISOString(),p_participant_limit:null,p_close_rule:'time_only',p_platform_partner_id:null,p_platform_url:null,p_required_matches:3,p_min_total_odds:1,p_max_total_odds:null,p_virtual_stake:100,p_image_url:null,p_metadata:{}});if(error)throw error;toast.success('Pick Rush created');await load()}catch(e){toast.error(errText(e))}}
 async function save(){try{const p={status:form.status,starts_at:form.starts_at,ends_at:form.ends_at,participant_limit:form.participant_limit?Number(form.participant_limit):null,close_rule:form.close_rule,platform_partner_id:form.platform_partner_id||null,platform_url:form.platform_url||null,required_matches:Number(form.required_matches),min_total_odds:Number(form.min_total_odds),max_total_odds:form.max_total_odds===''?null:Number(form.max_total_odds),virtual_stake:Number(form.virtual_stake),max_entries_per_user:Number(form.max_entries_per_user),campaign_percent:Number(form.campaign_percent),metadata:typeof form.metadata==='string'?parseJson(form.metadata):form.metadata??{}};const {error}=await supabase.from('pickrush_contests').update(p).eq('id',selected.id);if(error)throw error;await load();toast.success('Pick Rush saved')}catch(e){toast.error(errText(e))}}
 async function action(kind:string){try{let data,error;if(kind==='close')({data,error}=await supabase.rpc('close_pickrush',{p_contest_id:selected.id,p_reason:'Closed from Admin'}));else if(kind==='open')({data,error}=await supabase.rpc('open_pickrush',{p_contest_id:selected.id}));else if(kind==='lock')({data,error}=await supabase.rpc('lock_pickrush_contest',{p_contest_id:selected.id}));else if(kind==='finalize')({data,error}=await supabase.rpc('finalize_pickrush_contest',{p_contest_id:selected.id}));else ({data,error}=await supabase.rpc('refresh_pickrush_contest_state',{p_contest_id:selected.id}));if(error)throw error;toast.success(`${kind} complete`);console.debug(data);await load()}catch(e){toast.error(errText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Pick Rush" description="Contest lifecycle, rules, partner routing and participant operations." actions={<><Button variant="outline" onClick={()=>void load()}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button onClick={()=>void create()}><Plus className="h-4 w-4"/>Create contest</Button></>}/><Section title="Contests"><div className="grid gap-2">{rows.map(r=><button key={r.id} onClick={()=>pick(r)} className={`rounded-md border p-3 text-left ${selected?.id===r.id?'border-foreground':'border-border'}`}><div className="flex items-center justify-between"><div><div className="font-medium">{r.status}</div><div className="text-xs text-muted-foreground">{fmt(r.starts_at)} → {fmt(r.ends_at)}</div></div><StatusBadge status={r.status} dense/></div></button>)}</div></Section>{selected&&form&&<Section title="Contest controls"><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-4"><Field label="Status"><select className={inputCls} value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{['draft','scheduled','open','full','closed','awaiting_results','settling','completed','cancelled'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Starts"><input className={inputCls} type="datetime-local" value={form.starts_at?.slice?.(0,16)??''} onChange={e=>setForm({...form,starts_at:e.target.value})}/></Field><Field label="Ends"><input className={inputCls} type="datetime-local" value={form.ends_at?.slice?.(0,16)??''} onChange={e=>setForm({...form,ends_at:e.target.value})}/></Field><Field label="Participant limit"><input className={inputCls} type="number" value={form.participant_limit??''} onChange={e=>setForm({...form,participant_limit:e.target.value})}/></Field><Field label="Close rule"><select className={inputCls} value={form.close_rule} onChange={e=>setForm({...form,close_rule:e.target.value})}>{['time_only','participant_limit_only','time_or_limit','time_and_limit','manual'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Required matches"><input className={inputCls} type="number" value={form.required_matches} onChange={e=>setForm({...form,required_matches:e.target.value})}/></Field><Field label="Min total odds"><input className={inputCls} type="number" step="0.01" value={form.min_total_odds} onChange={e=>setForm({...form,min_total_odds:e.target.value})}/></Field><Field label="Max total odds"><input className={inputCls} type="number" step="0.01" value={form.max_total_odds??''} onChange={e=>setForm({...form,max_total_odds:e.target.value})}/></Field><Field label="Virtual stake"><input className={inputCls} type="number" value={form.virtual_stake} onChange={e=>setForm({...form,virtual_stake:e.target.value})}/></Field><Field label="Max entries/user"><input className={inputCls} type="number" value={form.max_entries_per_user} onChange={e=>setForm({...form,max_entries_per_user:e.target.value})}/></Field><Field label="Campaign %"><input className={inputCls} type="number" value={form.campaign_percent} onChange={e=>setForm({...form,campaign_percent:e.target.value})}/></Field><Field label="Platform URL"><input className={inputCls} value={form.platform_url??''} onChange={e=>setForm({...form,platform_url:e.target.value})}/></Field><Field label="Metadata JSON"><JsonField value={typeof form.metadata==='string'?form.metadata:JSON.stringify(form.metadata??{},null,2)} onChange={v=>setForm({...form,metadata:v})}/></Field></div><div className="mt-density-md flex flex-wrap gap-2"><Button variant="outline" onClick={()=>void action('open')}><Play className="h-4 w-4"/>Open</Button><Button variant="outline" onClick={()=>void action('lock')}><LockKeyhole className="h-4 w-4"/>Lock</Button><Button variant="outline" onClick={()=>void action('close')}><PowerOff className="h-4 w-4"/>Close</Button><Button variant="outline" onClick={()=>void action('finalize')}><Trophy className="h-4 w-4"/>Finalize</Button><Button variant="outline" onClick={()=>void action('refresh')}><RotateCcw className="h-4 w-4"/>Refresh state</Button><Button onClick={()=>void save()}><Save className="h-4 w-4"/>Save</Button></div><div className="mt-density-lg"><div className="mb-2 font-semibold">Participants</div><div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th className="py-2">User</th><th>Status</th><th>Code</th><th>Score</th><th>Rank</th></tr></thead><tbody>{participants.map((p:any,i:number)=><tr key={p.id??i} className="border-b border-border/70"><td className="py-2">{p.username??p.full_name??p.user_id}</td><td>{p.status}</td><td>{p.registration_code??'—'}</td><td>{p.score??0}</td><td>{p.rank??'—'}</td></tr>)}</tbody></table></div></div></Section>}</div>
}

export function PrizePoolPage(){
 const [rows,setRows]=useState<any[]>([]),[selected,setSelected]=useState<any|null>(null),[form,setForm]=useState<any>(null),[tiers,setTiers]=useState<any[]>([]),[rules,setRules]=useState<any[]>([]),[awards,setAwards]=useState<any[]>([])
 async function load(){try{const {data,error}=await supabase.from('prize_pool_campaigns').select('*').order('starts_at',{ascending:false});if(error)throw error;setRows(data??[]);if(selected){const c=(data??[]).find((r:any)=>r.id===selected.id);if(c){setSelected(c);setForm({...c,metadata:JSON.stringify(c.metadata??{},null,2),eligibility_rules:JSON.stringify(c.eligibility_rules??{},null,2)});const [t,r,a]=await Promise.all([supabase.from('prize_pool_reward_tiers').select('*').eq('campaign_id',c.id).order('sort_order'),supabase.from('prize_pool_eligibility_rules').select('*').eq('campaign_id',c.id).order('sort_order'),supabase.rpc('admin_get_prize_pool_awards',{p_campaign_id:c.id})]);setTiers(t.data??[]);setRules(r.data??[]);setAwards(Array.isArray(a.data)?a.data:[])}}}catch(e){toast.error(errText(e))}}useEffect(()=>{void load()},[])
 async function create(){try{const {error}=await supabase.rpc('create_prize_pool_campaign',{p_slug:`prize-pool-${Date.now()}`,p_title:'New Prize Pool',p_description:'',p_starts_at:new Date().toISOString(),p_ends_at:new Date(Date.now()+86400000*7).toISOString(),p_process_at:new Date(Date.now()+86400000*7+3600000).toISOString(),p_pool_amount:100,p_currency:'USD',p_rewarded_positions:10,p_leaderboard_metric:'current_balance'});if(error)throw error;toast.success('Prize pool created');await load()}catch(e){toast.error(errText(e))}}
 function pick(r:any){setSelected(r);setForm({...r,metadata:JSON.stringify(r.metadata??{},null,2),eligibility_rules:JSON.stringify(r.eligibility_rules??{},null,2)})}
 async function save(){try{const p={...form,pool_amount:Number(form.pool_amount),rewarded_positions:Number(form.rewarded_positions),max_entries_per_user:Number(form.max_entries_per_user),min_account_age_days:form.min_account_age_days===''||form.min_account_age_days==null?null:Number(form.min_account_age_days),metadata:parseJson(form.metadata),eligibility_rules:parseJson(form.eligibility_rules)};delete p.id;delete p.created_at;delete p.updated_at;const {error}=await supabase.from('prize_pool_campaigns').update(p).eq('id',selected.id);if(error)throw error;toast.success('Prize pool saved');await load()}catch(e){toast.error(errText(e))}}
 async function action(kind:string){try{let data,error;if(kind==='process')({data,error}=await supabase.rpc('process_prize_pool',{p_campaign_id:selected.id,p_force:false}));else if(kind==='status')({data,error}=await supabase.rpc('refresh_prize_pool_statuses'));else ({data,error}=await supabase.rpc('admin_set_prize_pool_status',{p_campaign_id:selected.id,p_status:form.status}));if(error)throw error;toast.success(`${kind} complete`);console.debug(data);await load()}catch(e){toast.error(errText(e))}}
 async function addTier(){try{const {error}=await supabase.from('prize_pool_reward_tiers').insert({campaign_id:selected.id,rank_from:1,rank_to:1,reward_amount:10,currency:form.currency,title:'New tier',description:'',sort_order:tiers.length});if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 async function addRule(){try{const {error}=await supabase.from('prize_pool_eligibility_rules').insert({campaign_id:selected.id,rule_key:`rule-${Date.now()}`,rule_type:'account_age',operator:'gte',value:{days:0},is_required:true,enabled:true,sort_order:rules.length,title:'Account age',description:'',metadata:{}});if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 async function del(table:string,id:string){if(!window.confirm('Delete item?'))return;try{const {error}=await supabase.from(table).delete().eq('id',id);if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Prize Pool" description="Campaigns, tiers, eligibility, processing and awards." actions={<><Button variant="outline" onClick={()=>void load()}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button onClick={()=>void create()}><Plus className="h-4 w-4"/>Create pool</Button></>}/><Section title="Campaigns"><div className="grid gap-2">{rows.map(r=><button key={r.id} onClick={()=>pick(r)} className={`rounded-md border p-3 text-left ${selected?.id===r.id?'border-foreground':'border-border'}`}><div className="flex items-center justify-between"><div><div className="font-medium">{r.title}</div><div className="text-xs text-muted-foreground">{r.pool_amount} {r.currency} · {fmt(r.starts_at)}</div></div><StatusBadge status={r.status} dense/></div></button>)}</div></Section>{selected&&form&&<Section title={`Manage: ${selected.title}`}><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-4"><Field label="Status"><select className={inputCls} value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{['draft','scheduled','open','closed','processing','processed','cancelled'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Starts"><input className={inputCls} type="datetime-local" value={form.starts_at?.slice?.(0,16)??''} onChange={e=>setForm({...form,starts_at:e.target.value})}/></Field><Field label="Ends"><input className={inputCls} type="datetime-local" value={form.ends_at?.slice?.(0,16)??''} onChange={e=>setForm({...form,ends_at:e.target.value})}/></Field><Field label="Process at"><input className={inputCls} type="datetime-local" value={form.process_at?.slice?.(0,16)??''} onChange={e=>setForm({...form,process_at:e.target.value})}/></Field><Field label="Pool amount"><input className={inputCls} type="number" value={form.pool_amount} onChange={e=>setForm({...form,pool_amount:e.target.value})}/></Field><Field label="Currency"><input className={inputCls} value={form.currency} onChange={e=>setForm({...form,currency:e.target.value})}/></Field><Field label="Rewarded positions"><input className={inputCls} type="number" value={form.rewarded_positions} onChange={e=>setForm({...form,rewarded_positions:e.target.value})}/></Field><Field label="Leaderboard metric"><select className={inputCls} value={form.leaderboard_metric} onChange={e=>setForm({...form,leaderboard_metric:e.target.value})}>{['current_balance','lifetime_earned'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Distribution"><select className={inputCls} value={form.distribution_method} onChange={e=>setForm({...form,distribution_method:e.target.value})}>{['equal','tiered'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Eligibility mode"><select className={inputCls} value={form.eligibility_mode} onChange={e=>setForm({...form,eligibility_mode:e.target.value})}>{['open','account_age','joined_only'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Max entries/user"><input className={inputCls} type="number" value={form.max_entries_per_user} onChange={e=>setForm({...form,max_entries_per_user:e.target.value})}/></Field><Field label="Min account age days"><input className={inputCls} type="number" value={form.min_account_age_days??''} onChange={e=>setForm({...form,min_account_age_days:e.target.value})}/></Field><Field label="Featured"><input type="checkbox" checked={!!form.featured} onChange={e=>setForm({...form,featured:e.target.checked})}/></Field><Field label="Sort order"><input className={inputCls} type="number" value={form.sort_order} onChange={e=>setForm({...form,sort_order:e.target.value})}/></Field><Field label="Image URL"><input className={inputCls} value={form.image_url??''} onChange={e=>setForm({...form,image_url:e.target.value})}/></Field><Field label="Cover URL"><input className={inputCls} value={form.cover_url??''} onChange={e=>setForm({...form,cover_url:e.target.value})}/></Field><div className="md:col-span-2 xl:col-span-4"><Field label="Metadata JSON"><JsonField value={form.metadata} onChange={v=>setForm({...form,metadata:v})}/></Field></div><div className="md:col-span-2 xl:col-span-4"><Field label="Eligibility rules JSON"><JsonField value={form.eligibility_rules} onChange={v=>setForm({...form,eligibility_rules:v})}/></Field></div></div><div className="mt-density-md flex flex-wrap justify-between gap-2"><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={()=>void action('status')}><RotateCcw className="h-4 w-4"/>Refresh statuses</Button><Button variant="outline" onClick={()=>void action('process')}><Play className="h-4 w-4"/>Process</Button><Button variant="outline" onClick={()=>void action('apply')}><Power className="h-4 w-4"/>Apply status</Button></div><Button onClick={()=>void save()}><Save className="h-4 w-4"/>Save</Button></div><div className="mt-density-xl grid gap-density-lg xl:grid-cols-3"><div><div className="mb-2 font-semibold">Reward tiers</div>{tiers.map(t=><div key={t.id} className="mb-2 flex items-center justify-between rounded-md border border-border p-3"><div>#{t.rank_from}-{t.rank_to} · {t.reward_amount} {t.currency}</div><Button variant="ghost" size="sm" onClick={()=>void del('prize_pool_reward_tiers',t.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div>)}<Button size="sm" variant="outline" onClick={()=>void addTier()}><Plus className="h-3.5 w-3.5"/>Add tier</Button></div><div><div className="mb-2 font-semibold">Eligibility rules</div>{rules.map(r=><div key={r.id} className="mb-2 flex items-center justify-between rounded-md border border-border p-3"><div><div className="font-medium">{r.title||r.rule_key}</div><div className="text-xs text-muted-foreground">{r.rule_type} · {r.operator}</div></div><Button variant="ghost" size="sm" onClick={()=>void del('prize_pool_eligibility_rules',r.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div>)}<Button size="sm" variant="outline" onClick={()=>void addRule()}><Plus className="h-3.5 w-3.5"/>Add rule</Button></div><div><div className="mb-2 font-semibold">Awards</div>{awards.map((a:any,i:number)=><div key={a.id??i} className="mb-2 rounded-md border border-border p-3 text-sm">Rank {a.rank} · {a.amount} {a.currency}<div className="text-xs text-muted-foreground">{a.status} · {a.user_id}</div></div>)}{awards.length===0&&<div className="text-sm text-muted-foreground">No awards yet.</div>}</div></div></Section>}</div>
}

export function BookmakersRadarPage(){
 const [rows,setRows]=useState<any[]>([]),[reports,setReports]=useState<any[]>([]),[incidents,setIncidents]=useState<any[]>([]),[selected,setSelected]=useState<any|null>(null),[form,setForm]=useState<any>(null)
 async function load(){try{const [{data:b,error:be},{data:r,error:re},{data:i,error:ie}]=await Promise.all([supabase.from('bookmakers_radar').select('*').order('priority').order('name'),supabase.from('bookmaker_reports').select('*').order('submitted_at',{ascending:false}),supabase.from('bookmaker_incidents').select('*').order('published_at',{ascending:false})]);if(be)throw be;if(re)throw re;if(ie)throw ie;setRows(b??[]);setReports(r??[]);setIncidents(i??[])}catch(e){toast.error(errText(e))}}useEffect(()=>{void load()},[])
 function pick(r:any){setSelected(r);setForm({...r,metadata:JSON.stringify(r.metadata??{},null,2)})}
 async function create(){try{const {data,error}=await supabase.from('bookmakers_radar').insert({name:'New Bookmaker',slug:`bookmaker-${Date.now()}`,status:'inactive'}).select().single();if(error)throw error;pick(data);await load()}catch(e){toast.error(errText(e))}}
 async function save(){try{const p={...form,radar_score:form.radar_score===''?null:Number(form.radar_score),verified_reports:Number(form.verified_reports)||0,unresolved_reports:Number(form.unresolved_reports)||0,resolved_reports:Number(form.resolved_reports)||0,repeated_patterns:Number(form.repeated_patterns)||0,priority:Number(form.priority)||100,metadata:parseJson(form.metadata)};delete p.id;delete p.created_at;delete p.updated_at;const {error}=await supabase.from('bookmakers_radar').update(p).eq('id',selected.id);if(error)throw error;toast.success('Bookmaker saved');await load()}catch(e){toast.error(errText(e))}}
 async function remove(){if(!selected||!window.confirm('Delete this bookmaker?'))return;try{const {error}=await supabase.from('bookmakers_radar').delete().eq('id',selected.id);if(error)throw error;setSelected(null);await load()}catch(e){toast.error(errText(e))}}
 async function recompute(id?:string){try{const {error}=id?await supabase.rpc('recompute_bookmaker_radar',{p_bookmaker_id:id}):await supabase.rpc('recompute_all_bookmakers_radar');if(error)throw error;toast.success('Radar recomputed');await load()}catch(e){toast.error(errText(e))}}
 async function publish(r:any){try{const {error}=await supabase.rpc('admin_publish_bookmaker_report',{p_report_id:r.id,p_title:r.custom_brand_name??r.reference_code,p_summary:r.description,p_severity:'moderate',p_evidence_strength:'moderate',p_resolution_status:'unresolved',p_amount:r.amount??null,p_currency:r.currency??null});if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 async function resolve(i:any){try{const {error}=await supabase.rpc('admin_resolve_bookmaker_incident',{p_incident_id:i.id,p_resolution_note:'Resolved from Admin Radar'});if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Bookmakers Radar" description="Bookmaker metadata, verification, radar signals, reports and incidents." actions={<><Button variant="outline" onClick={()=>void load()}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button variant="outline" onClick={()=>void recompute()}><RotateCcw className="h-4 w-4"/>Recompute all</Button><Button onClick={()=>void create()}><Plus className="h-4 w-4"/>New bookmaker</Button></>}/><Section title="Bookmakers"><div className="grid gap-2 md:grid-cols-2 xl:grid-cols-3">{rows.map(r=><button key={r.id} onClick={()=>pick(r)} className={`rounded-md border p-3 text-left ${selected?.id===r.id?'border-foreground':'border-border'}`}><div className="flex items-center justify-between"><div><div className="font-medium">{r.name}</div><div className="text-xs text-muted-foreground">{r.slug} · priority {r.priority}</div></div><StatusBadge status={r.status} dense/></div><div className="mt-2 text-xs text-muted-foreground">Radar {r.radar_score??'—'} · {r.risk_level} · {r.current_signal}</div></button>)}</div></Section>{selected&&form&&<Section title={`Edit: ${selected.name}`} actions={<Button variant="ghost" size="sm" onClick={remove}><Trash2 className="h-3.5 w-3.5"/>Delete</Button>}><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-4"><Field label="Name"><input className={inputCls} value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Field><Field label="Slug"><input className={inputCls} value={form.slug} onChange={e=>setForm({...form,slug:e.target.value})}/></Field><Field label="Short name"><input className={inputCls} value={form.short_name??''} onChange={e=>setForm({...form,short_name:e.target.value})}/></Field><Field label="Logo URL"><input className={inputCls} value={form.logo_url??''} onChange={e=>setForm({...form,logo_url:e.target.value})}/></Field><Field label="Cover URL"><input className={inputCls} value={form.cover_url??''} onChange={e=>setForm({...form,cover_url:e.target.value})}/></Field><Field label="Website"><input className={inputCls} value={form.website??''} onChange={e=>setForm({...form,website:e.target.value})}/></Field><Field label="License"><input className={inputCls} value={form.license_name??''} onChange={e=>setForm({...form,license_name:e.target.value})}/></Field><Field label="License verified"><input type="checkbox" checked={!!form.license_verified} onChange={e=>setForm({...form,license_verified:e.target.checked})}/></Field><Field label="Country"><input className={inputCls} value={form.country??''} onChange={e=>setForm({...form,country:e.target.value})}/></Field><Field label="Status"><select className={inputCls} value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{['active','inactive','archived'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Radar score"><input className={inputCls} type="number" min="0" max="100" value={form.radar_score??''} onChange={e=>setForm({...form,radar_score:e.target.value})}/></Field><Field label="Risk"><select className={inputCls} value={form.risk_level} onChange={e=>setForm({...form,risk_level:e.target.value})}>{['low','medium','high','critical','insufficient_data'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Confidence"><select className={inputCls} value={form.confidence_level} onChange={e=>setForm({...form,confidence_level:e.target.value})}>{['limited','moderate','high'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Evidence strength"><select className={inputCls} value={form.evidence_strength} onChange={e=>setForm({...form,evidence_strength:e.target.value})}>{['limited','moderate','strong'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Current signal"><select className={inputCls} value={form.current_signal} onChange={e=>setForm({...form,current_signal:e.target.value})}>{['strong_safety_signals','generally_stable','mixed_safety_signals','elevated_concern','critical_concern','insufficient_data'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Trend"><select className={inputCls} value={form.trend} onChange={e=>setForm({...form,trend:e.target.value})}>{['improving','stable','worsening','no_data'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Verified"><input type="checkbox" checked={!!form.verified} onChange={e=>setForm({...form,verified:e.target.checked})}/></Field><Field label="Featured"><input type="checkbox" checked={!!form.featured} onChange={e=>setForm({...form,featured:e.target.checked})}/></Field><Field label="Sharp"><input type="checkbox" checked={!!form.is_sharp} onChange={e=>setForm({...form,is_sharp:e.target.checked})}/></Field><Field label="Provider enabled"><input type="checkbox" checked={!!form.data_provider_enabled} onChange={e=>setForm({...form,data_provider_enabled:e.target.checked})}/></Field><Field label="Priority"><input className={inputCls} type="number" value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}/></Field><Field label="Discovery source"><select className={inputCls} value={form.discovery_source??'admin'} onChange={e=>setForm({...form,discovery_source:e.target.value})}>{['admin','system','user_report','import'].map(v=><option key={v}>{v}</option>)}</select></Field><div className="md:col-span-2 xl:col-span-4"><Field label="Description"><textarea className={areaCls} value={form.description??''} onChange={e=>setForm({...form,description:e.target.value})}/></Field></div><div className="md:col-span-2 xl:col-span-4"><Field label="Metadata JSON"><JsonField value={form.metadata} onChange={v=>setForm({...form,metadata:v})}/></Field></div></div><div className="mt-density-md flex justify-end gap-2"><Button variant="outline" onClick={()=>void recompute(selected.id)}><RotateCcw className="h-4 w-4"/>Recompute</Button><Button onClick={()=>void save()}><Save className="h-4 w-4"/>Save</Button></div></Section>}
 <div className="grid gap-density-lg xl:grid-cols-2"><Section title="Reports"><div className="space-y-2">{reports.map(r=><div key={r.id} className="rounded-md border border-border p-3"><div className="flex items-center justify-between"><div><div className="font-medium">{r.reference_code}</div><div className="text-xs text-muted-foreground">{r.category} · {fmt(r.submitted_at)}</div></div><StatusBadge status={r.status} dense/></div>{['submitted','under_review'].includes(r.status)&&<div className="mt-2 flex justify-end"><Button size="sm" variant="outline" onClick={()=>void publish(r)}>Publish / verify</Button></div>}</div>)}</div></Section><Section title="Incidents"><div className="space-y-2">{incidents.map(i=><div key={i.id} className="rounded-md border border-border p-3"><div className="flex items-center justify-between"><div className="font-medium">{i.title}</div><StatusBadge status={i.resolution_status} dense/></div><div className="mt-1 text-xs text-muted-foreground">{i.severity} · {i.evidence_strength}</div>{i.resolution_status==='unresolved'&&<div className="mt-2 flex justify-end"><Button size="sm" variant="outline" onClick={()=>void resolve(i)}>Resolve</Button></div>}</div>)}</div></Section></div></div>
}

export function LeaderboardsPage(){
 const blank={username:'',full_name:'',avatar_id:'',points:0,is_active:true,date_of_birth:'',country:'',city:'',address:'',facebook:'',telegram:'',whatsapp:'',bio:'',phone:'',status:'active'};const [board,setBoard]=useState<any[]>([]),[bots,setBots]=useState<any[]>([]),[bot,setBot]=useState<any>(blank),[editing,setEditing]=useState<string|null>(null)
 async function load(){try{const [{data:b,error:be},{data:bo,error:boe}]=await Promise.all([supabase.rpc('get_leaderboard',{p_limit:100,p_offset:0}),supabase.from('leaderboard_bots').select('*').order('points',{ascending:false})]);if(be)throw be;if(boe)throw boe;setBoard(Array.isArray(b)?b:[]);setBots(bo??[])}catch(e){toast.error(errText(e))}}useEffect(()=>{void load()},[])
 function edit(r:any){setEditing(r.id);setBot({...r})}function fresh(){setEditing(null);setBot({...blank})}
 async function save(){try{const p={...bot,points:Number(bot.points)||0};delete p.id;delete p.created_at;delete p.last_activity_at;delete p.current_balance;delete p.lifetime_earned;const q=editing?await supabase.from('leaderboard_bots').update(p).eq('id',editing):await supabase.from('leaderboard_bots').insert(p);if(q.error)throw q.error;toast.success(editing?'Bot updated':'Bot created');fresh();await load()}catch(e){toast.error(errText(e))}}
 async function del(id:string){if(!window.confirm('Delete this leaderboard bot?'))return;try{const {error}=await supabase.from('leaderboard_bots').delete().eq('id',id);if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Leaderboards" description="Live leaderboard plus synthetic leaderboard bot administration." actions={<><Button variant="outline" onClick={()=>void load()}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button onClick={fresh}><Plus className="h-4 w-4"/>New bot</Button></>}/><Section title="Live leaderboard"><div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th className="py-2">Rank</th><th>User</th><th>Points</th><th>Current user</th></tr></thead><tbody>{board.map((r:any,i:number)=><tr key={r.user_id??i} className="border-b border-border/70"><td className="py-2">{r.rank}</td><td>{r.username??r.full_name??r.user_id}</td><td>{Number(r.points??0).toLocaleString()}</td><td>{r.is_current_user?'Yes':''}</td></tr>)}</tbody></table></div></Section><Section title={editing?'Edit leaderboard bot':'Create leaderboard bot'}><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-4"><Field label="Username"><input className={inputCls} value={bot.username} onChange={e=>setBot({...bot,username:e.target.value})}/></Field><Field label="Full name"><input className={inputCls} value={bot.full_name??''} onChange={e=>setBot({...bot,full_name:e.target.value})}/></Field><Field label="Points"><input className={inputCls} type="number" value={bot.points} onChange={e=>setBot({...bot,points:e.target.value})}/></Field><Field label="Status"><input className={inputCls} value={bot.status??''} onChange={e=>setBot({...bot,status:e.target.value})}/></Field><Field label="Country"><input className={inputCls} value={bot.country??''} onChange={e=>setBot({...bot,country:e.target.value})}/></Field><Field label="City"><input className={inputCls} value={bot.city??''} onChange={e=>setBot({...bot,city:e.target.value})}/></Field><Field label="Avatar ID"><input className={inputCls} value={bot.avatar_id??''} onChange={e=>setBot({...bot,avatar_id:e.target.value})}/></Field><Field label="Active"><input type="checkbox" checked={!!bot.is_active} onChange={e=>setBot({...bot,is_active:e.target.checked})}/></Field><Field label="Phone"><input className={inputCls} value={bot.phone??''} onChange={e=>setBot({...bot,phone:e.target.value})}/></Field><Field label="Bio"><input className={inputCls} value={bot.bio??''} onChange={e=>setBot({...bot,bio:e.target.value})}/></Field></div><div className="mt-density-md flex justify-end gap-2"><Button variant="outline" onClick={fresh}>Clear</Button><Button onClick={()=>void save()}><Save className="h-4 w-4"/>Save bot</Button></div></Section><Section title="Bots"><div className="grid gap-2 md:grid-cols-2 xl:grid-cols-3">{bots.map(r=><div key={r.id} className="rounded-md border border-border p-3"><div className="flex items-center justify-between"><div><div className="font-medium">{r.username}</div><div className="text-xs text-muted-foreground">{r.full_name??'—'} · {Number(r.points).toLocaleString()}</div></div><StatusBadge status={r.is_active?'ACTIVE':'DISABLED'} dense/></div><div className="mt-2 flex justify-end gap-1"><Button variant="ghost" size="sm" onClick={()=>edit(r)}>Edit</Button><Button variant="ghost" size="sm" onClick={()=>void del(r.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div></div>)}</div></Section></div>
}
